def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_def = 0
    for h in history:
        if h[1] == 'D':
            opp_def += 1

    if opp_def > n * 0.5:
        return 'D'

    if n >= 10:
        recent_opp_def = 0
        for h in history[-10:]:
            if h[1] == 'D':
                recent_opp_def += 1
        if recent_opp_def >= 8:
            return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        if last_me == 'C' and n >= 2 and history[-2] == ('D', 'D'):
            return 'C'
        return 'D'

    if last_me == 'D':
        if opp_def <= n * 0.1:
            return 'D'
        return 'C'

    if opp_def == 0 and n > 50:
        my_def_recent = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                my_def_recent += 1
            else:
                break
        if my_def_recent == 0:
            return 'D'

    return 'C'
